package pe.vichaval.gestionriego.finanzas.controller;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import pe.vichaval.gestionriego.finanzas.dto.ConceptoCobroForm;import pe.vichaval.gestionriego.finanzas.service.FinanzasService;@Controller@RequestMapping("/tesoreria/conceptos")public class ConceptoCobroWebController{private final FinanzasService s;public ConceptoCobroWebController(FinanzasService s){this.s=s;}@GetMapping String listar(Model m){m.addAttribute("conceptos",s.listarConceptos());m.addAttribute("form",new ConceptoCobroForm());return "finanzas/conceptos";}@PostMapping String guardar(@Valid@ModelAttribute("form")ConceptoCobroForm f,BindingResult b,Model m,RedirectAttributes ra){if(b.hasErrors()){m.addAttribute("conceptos",s.listarConceptos());return "finanzas/conceptos";}try{s.crearConcepto(f);ra.addFlashAttribute("exito","Concepto creado");return "redirect:/tesoreria/conceptos";}catch(RuntimeException e){b.reject("negocio",e.getMessage());m.addAttribute("conceptos",s.listarConceptos());return "finanzas/conceptos";}}}
